function toast(msg){let t=$("#toast");if(!t){t=document.createElement("div");t.id="toast";t.className="toast";document.body.append(t)}t.textContent=String(msg);t.classList.add("show");clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove("show"),2200)}
function cart(){return get("nivora_cart",[]).filter(x=>x&&typeof x.id==="string"&&Number.isInteger(x.qty)&&x.qty>0)}
