function add(id){const p=products.find(x=>x.id===id);if(!p||p.stock<1)return toast("هذا المنتج غير متاح حالياً");let c=cart(),i=c.find(x=>x.id===id);if(i){if(i.qty>=p.stock)return toast("لا يمكن تجاوز الكمية المتاحة");i.qty++}else c.push({id,qty:1});saveCart(c);toast("تمت إضافة المنتج إلى السلة");window.NivoraFirebase?.trackEvent({type:"cart_add",productId:String(id),metadata:{category:p.cat||"other"}}).catch(()=>{})}
