function footer(){return `<footer class="footer"><div class="newsletter"><div class="container newsletter-inner"><div><span class="eyebrow">NIVORA NEWSLETTER</span><h2>كن أول من يعرف جديد NIVORA</h2><p>عروض خاصة، إطلاقات جديدة ومجموعات مختارة تصل إلى بريدك.</p></div><form class="newsletter-form" id="newsletter-form"><input type="email" name="email" autocomplete="email" required placeholder="بريدك الإلكتروني" aria-label="البريد الإلكتروني"><button class="btn-primary" type="submit">اشترك الآن</button></form></div></div><div class="container footer-grid"><div class="footer-brand"><div class="brand footer-brandmark"><img src="assets/logo/logo-transparent.webp" alt="NIVORA SILVER"><span><strong>NIVORA</strong><small>SILVER • LUXURY STORE</small></span></div><p>JEWELRY • PERFUME • WATCHES • SUNGLASSES</p><div class="socials"><a href="#" aria-label="Instagram">◎</a><a href="#" aria-label="Facebook">f</a><a href="#" aria-label="TikTok">♪</a><a href="#" aria-label="X">𝕏</a></div></div><div><b>روابط سريعة</b><a href="index.html">الرئيسية</a><a href="shop.html">المتجر</a><a href="offers.html">العروض</a><a href="about.html">من نحن</a><a href="contact.html">تواصل معنا</a></div><div><b>خدمة العملاء</b><a href="faq.html">الأسئلة الشائعة</a><a href="shipping.html">الشحن</a><a href="returns.html">الاسترجاع</a><a href="privacy.html">الخصوصية</a><a href="terms.html">الشروط والأحكام</a></div><div><b>تواصل معنا</b><span>القاهرة، مصر</span><a href="mailto:info@nivora.com">info@nivora.com</a><span>خدمة العملاء يومياً</span></div></div><div class="footer-bottom"><div class="container"><span>© 2026 NIVORA SILVER — جميع الحقوق محفوظة</span><span>Luxury in Every Detail</span></div></div></footer>`}
function shell(content,active){document.body.innerHTML=header(active)+`<main>${content}</main>`+footer()+`<div id="toast" class="toast" role="status" aria-live="polite"></div>`;updateHeader();bindGlobalUi()}
function card(p){const dis=p.old?Math.round((1-p.price/p.old)*100):0;const fav=get("nivora_fav",[]).includes(p.id);return `<article class="card"><div class="card-media"><a href="product.html?id=${encodeURIComponent(p.id)}" aria-label="عرض ${esc(p.name)}"><img src="${esc(p.img)}" alt="${esc(p.name)}" loading="lazy" decoding="async"></a>${dis?`<span class="badge">خصم ${dis}%</span>`:""}<button class="fav ${fav?'active':''}" type="button" data-fav="${esc(p.id)}" aria-label="${fav?'إزالة من المفضلة':'إضافة للمفضلة'}">${fav?'♥':'♡'}</button></div><div class="card-body"><span class="tag">${esc(p.catName)}</span><h3>${esc(p.name)}</h3><div class="rating" aria-label="تقييم 4.9 من 5">★★★★★ <span>4.9</span></div><div class="price-row"><span class="price">${money(p.price)}</span>${p.old?`<span class="old">${money(p.old)}</span>`:""}</div><div class="card-actions"><button class="btn-primary" type="button" data-add="${esc(p.id)}">أضف إلى السلة</button><a class="btn" href="product.html?id=${encodeURIComponent(p.id)}">عرض التفاصيل</a></div></div></article>`}
function bind(){ $$('[data-add]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound="1";b.addEventListener("click",()=>add(b.dataset.add))});$$('[data-fav]').forEach(b=>{if(b.dataset.bound)return;b.dataset.bound="1";b.addEventListener("click",()=>{let f=get("nivora_fav",[]);f=f.includes(b.dataset.fav)?f.filter(x=>x!==b.dataset.fav):[...f,b.dataset.fav];set("nivora_fav",f);window.NivoraFirebase?.trackEvent({type:f.includes(b.dataset.fav)?"favorite_add":"favorite_remove",productId:String(b.dataset.fav),metadata:{}}).catch(()=>{});const active=f.includes(b.dataset.fav);b.classList.toggle("active",active);b.textContent=active?"♥":"♡";b.setAttribute("aria-label",active?"إزالة من المفضلة":"إضافة للمفضلة")})});updateHeader()}
function bindGlobalUi(){
  if(!$("#privacy-consent")){ const choice=localStorage.getItem("nivora_tracking_consent"); if(!choice){ const b=document.createElement("div"); b.id="privacy-consent"; b.className="panel"; b.style.cssText="position:fixed;bottom:14px;left:14px;right:14px;z-index:9999;box-shadow:0 15px 40px rgba(0,0,0,.45);background:#0b0b0d;border:1px solid rgba(255,255,255,.12)"; b.innerHTML=`<strong>الخصوصية والتجربة</strong><p class="muted">يمكننا استخدام بيانات التصفح والاهتمامات لتحسين المتجر وقياس الأداء وتخصيص العروض. يمكنك الرفض أو القبول من هنا.</p><div class="toolbar"><button class="btn-primary" id="consent-yes">موافقة</button><button class="btn" id="consent-no">رفض</button><a class="btn" href="privacy.html">سياسة الخصوصية</a></div>`;document.body.append(b);$("#consent-yes").onclick=()=>{localStorage.setItem("nivora_tracking_consent","granted");window.dispatchEvent(new Event("nivora-consent-granted"));b.remove()};$("#consent-no").onclick=()=>{localStorage.setItem("nivora_tracking_consent","denied");b.remove()}; } }
  const menu=$("[data-menu-toggle]"),nav=$(".nav");if(menu&&nav)menu.addEventListener("click",()=>{nav.classList.toggle("mobile-open");menu.setAttribute("aria-expanded",String(nav.classList.contains("mobile-open")))});const search=$("#global-search");if(search)search.addEventListener("keydown",e=>{if(e.key==="Enter"){const q=search.value.trim();location.href=`search.html${q?`?q=${encodeURIComponent(q)}`:""}`}});const form=$("#newsletter-form");if(form)form.addEventListener("submit",e=>{e.preventDefault();const email=new FormData(form).get("email");if(email){set("nivora_newsletter",String(email).trim().toLowerCase());toast("تم تسجيل بريدك بنجاح");form.reset();window.NivoraFirebase?.trackEvent({type:"newsletter_signup",metadata:{source:"footer"}}).catch(()=>{})}});}
function grid(list){return `<div class="grid">${list.map(card).join("")}</div>`}
function home(){shell(`<section class="hero"><div class="hero-bg" role="img" aria-label="مجموعة NIVORA الفاخرة"></div><div class="hero-shade"></div><div class="container hero-inner"><div class="hero-copy"><span class="eyebrow">NIVORA SILVER • LUXURY STORE</span><h1>كل ما يميزك<br><span>في مكان واحد</span></h1><p>مجوهرات • ساعات • عطور • نظارات شمسية</p><div class="hero-actions"><a class="btn-primary" href="shop.html">تسوق الآن <span>←</span></a><a class="btn hero-secondary" href="offers.html">اكتشف العروض</a></div><div class="hero-meta"><span>01 / 04</span><i></i><span>تشكيلة فاخرة مختارة بعناية</span></div></div></div><button class="hero-arrow hero-arrow-next" type="button" aria-label="العرض التالي">‹</button><button class="hero-arrow hero-arrow-prev" type="button" aria-label="العرض السابق">›</button><div class="hero-dots" aria-hidden="true"><i class="active"></i><i></i><i></i></div></section><section class="section categories-section"><div class="container"><div class="section-head"><div><div class="eyebrow">COLLECTION</div><h2>تسوق حسب الفئة</h2><p class="muted">اكتشف مجموعات NIVORA SILVER المصممة لإطلالتك.</p></div><a class="btn" href="shop.html">عرض الكل ←</a></div><div class="categories">${[['jewelry','المجوهرات','تفاصيل تصنع الفارق',imgs.jewelry[0]],['watches','الساعات','دقة وأناقة خالدة',imgs.watch[0]],['perfumes','العطور','رائحة لا تُنسى',imgs.perfume[0]],['sunglasses','النظارات الشمسية','إطلالة تعكس شخصيتك',imgs.sunglasses[0]]].map(x=>`<a class="category" href="shop.html?category=${x[0]}" style="--category-image:url('${esc(x[3])}')"><div><span>${x[1]}</span><h3>${x[2]}</h3><small>اكتشف المجموعة ←</small></div></a>`).join("")}</div></div></section><section class="section products-section"><div class="container"><div class="section-head"><div><div class="eyebrow">NIVORA COLLECTION</div><h2>الأكثر مبيعاً</h2><p class="muted">قطع مختارة بعناية لتكمل حضورك.</p></div><a class="btn" href="shop.html">عرض الكل ←</a></div>${grid(products.slice(0,5))}</div></section><section class="editorial"><div class="editorial-image"></div><div class="editorial-copy"><span class="eyebrow">THE NIVORA EXPERIENCE</span><h2>مجموعة مختارة لك</h2><p>أحدث الصيحات وأرقى الاختيارات في تجربة واحدة، بتفاصيل تعكس هوية NIVORA.</p><a class="btn-primary" href="shop.html">تسوق المجموعة</a></div><div class="editorial-mini">${products.slice(0,4).map(p=>`<a href="product.html?id=${encodeURIComponent(p.id)}"><img src="${esc(p.img)}" alt="${esc(p.name)}" loading="lazy"></a>`).join("")}</div></section><section class="benefits"><div class="container benefits-grid"><div><span>♧</span><strong>تغليف فاخر</strong><small>يليق بكل طلب</small></div><div><span>◈</span><strong>دفع آمن</strong><small>بجميع وسائل الدفع</small></div><div><span>⌁</span><strong>شحن سريع</strong><small>لجميع أنحاء مصر</small></div><div><span>↺</span><strong>استرجاع سهل</strong><small>خلال 14 يوم</small></div><div><span>♧</span><strong>دعم العملاء</strong><small>على مدار الساعة</small></div></div></section><section class="testimonials section"><div class="container"><div class="section-head"><div><div class="eyebrow">NIVORA COMMUNITY</div><h2>آراء عملائنا</h2></div></div><div class="testimonial-grid"><article><div class="stars">★★★★★</div><p>“تجربة راقية من أول زيارة حتى التغليف. التفاصيل فعلاً مختلفة.”</p><strong>محمد علي</strong><small>عميل موثّق</small></article><article><div class="stars">★★★★★</div><p>“المنتج وصل كما في الصور والتغليف ممتاز. سأطلب مرة أخرى.”</p><strong>سارة خالد</strong><small>عميلة موثّقة</small></article><article><div class="stars">★★★★★</div><p>“واجهة المتجر سهلة والاختيارات واضحة، والتجربة بالكامل مريحة.”</p><strong>أحمد محمد</strong><small>عميل موثّق</small></article></div></div></section>`,`home`);bind();const hero=$(".hero");hero?.querySelectorAll(".hero-arrow").forEach(btn=>btn.addEventListener("click",()=>toast("سيتم تفعيل الشرائح الديناميكية من لوحة الإدارة")))}
function shop(category){let list=category?products.filter(p=>p.cat===category):products;let title=category?list[0]?.catName||"المتجر":"جميع المنتجات";shell(`<section class="page container"><div class="page-title"><div class="eyebrow">NIVORA COLLECTION</div><h1>${title}</h1><p class="muted">${list.length} منتجات متاحة</p></div><div class="toolbar"><input class="field search-field" id="q" placeholder="ابحث عن منتج..."><select class="field" id="sort"><option value="">ترتيب المنتجات</option><option value="low">السعر: الأقل</option><option value="high">السعر: الأعلى</option></select></div><div id="products-grid">${grid(list)}</div></section>`,"shop");function render(){let q=$("#q").value.trim().toLowerCase(),l=list.filter(p=>p.name.toLowerCase().includes(q));if($("#sort").value==="low")l.sort((a,b)=>a.price-b.price);if($("#sort").value==="high")l.sort((a,b)=>b.price-a.price);$("#products-grid").innerHTML=grid(l);bind()}$("#q").oninput=render;$("#sort").onchange=render;bind()}
function productPage(){
  let id=new URLSearchParams(location.search).get("id")||"N001",p=products.find(x=>x.id===id)||products[0];
  const gallery=Array.from(new Set([p.img,...(Array.isArray(p.images)?p.images:[]),...(imgs[p.cat]||[])].filter(Boolean))).slice(0,6);
  shell(`<section class="page container"><div class="product-detail"><div><div class="gallery-main"><img id="main-img" src="${esc(p.img)}" alt="${esc(p.name)}"></div><div class="thumbs">${gallery.map((x,i)=>`<button class="thumb-btn" type="button" data-gallery-src="${esc(x)}"><img src="${esc(x)}" alt="${esc(p.name)} ${i+1}"></button>`).join("")}</div></div><div><span class="tag">${esc(p.catName)}</span><h1>${esc(p.name)}</h1><div class="rating">★★★★★ تقييم ممتاز</div><h2 class="price">${money(p.price)} ${p.old?`<span class="old">${money(p.old)}</span>`:""}</h2><p class="muted">${esc(p.desc)}</p><div class="notice">متوفر في المخزون: ${Number(p.stock)||0} قطعة</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><button class="btn-primary" data-add="${esc(p.id)}">أضف للسلة</button><a class="btn" href="checkout.html?product=${encodeURIComponent(p.id)}">اشتر الآن</a><button class="btn" id="request-product">اطلب توفير هذا المنتج</button></div><div id="request-msg" class="message" style="margin-top:14px"></div></div></div></section>`);
  bind();
  $$('[data-gallery-src]').forEach(b=>b.addEventListener('click',()=>{const img=$("#main-img");if(img)img.src=b.dataset.gallerySrc}));
  const req=$("#request-product");
  if(req) req.onclick=async()=>{
    try{
      const user=await window.NivoraFirebase?.currentUser();
      if(!user)return location.href=`login.html?next=${encodeURIComponent(location.href)}`;
      req.disabled=true; req.textContent="جارٍ إرسال الطلب...";
      const requestId=await window.NivoraFirebase.createProductRequest({productId:String(p.id),productName:String(p.name),productImage:String(p.img||""),sourceUrl:String(p.sourceUrl||""),category:String(p.cat||"other"),requestedQty:1});
      $("#request-msg").textContent=`تم إرسال طلب التوفير #${requestId}. سيظهر للمدير لمتابعته.`; $("#request-msg").classList.add("show");
      await window.NivoraFirebase.trackEvent({type:"product_request",productId:String(p.id),metadata:{source:p.source||"catalog"}});
    }catch(e){$("#request-msg").textContent=e.message||"تعذر إرسال الطلب";$("#request-msg").classList.add("show");req.disabled=false;req.textContent="اطلب توفير هذا المنتج"}
  };
  window.NivoraFirebase?.trackEvent({type:"view_product",productId:String(p.id),metadata:{category:p.cat||"other"}}).catch(()=>{});
}

function indexGate(){
  document.body.innerHTML=`<div class="nv-splash"><div class="nv-splash-inner"><img src="assets/logo/logo-transparent.webp" alt="NIVORA SILVER" class="nv-splash-logo"><div class="eyebrow">SILVER • LUXURY STORE</div><h1>فخامة تبدأ من التفاصيل</h1><p>أناقة مختارة بعناية، وتجربة صنعت لتبقى.</p><div class="nv-loader"><i></i></div></div></div>`;
  setTimeout(()=>home(),180);
}
function register(){shell(`<section class="page container"><form class="form" id="register-form"><div class="eyebrow">NIVORA ACCOUNT</div><h2>إنشاء حساب جديد</h2><p class="muted">أنشئ حسابك كعميل للمتابعة والشراء.</p><div id="msg" class="message"></div><div class="form-row"><label>الاسم</label><input autocomplete="name" class="field" id="name" required></div><div class="form-row"><label>البريد الإلكتروني</label><input autocomplete="email" class="field" id="email" type="email" required></div><div class="form-row"><label>كلمة المرور</label><input autocomplete="new-password" class="field" id="pass" type="password" minlength="6" required></div><button class="btn-primary" id="register-submit" style="width:100%">إنشاء الحساب</button><div class="form-links"><a href="login.html">العودة لتسجيل الدخول</a></div></form></section>`);$("#register-form").onsubmit=async e=>{e.preventDefault();const btn=$("#register-submit");btn.disabled=true;btn.textContent="جارٍ إنشاء الحساب...";try{if(!window.NivoraFirebase?.enabled)throw new Error("Firebase غير مهيأ");let u=await window.NivoraFirebase.register($("#name").value.trim(),$("#email").value.trim(),$("#pass").value);set("nivora_user",{uid:u.uid,name:u.displayName,email:u.email,role:"customer"});location.href="account.html"}catch(err){showMsg(err.code==="auth/email-already-in-use"?"البريد مستخدم بالفعل":err.message);btn.disabled=false;btn.textContent="إنشاء الحساب"}}}
