  const cards=offers.length?offers.map(o=>{const image=String(o.image||'assets/logo/logo-transparent.webp');const url=safeExternalUrl(o.url||'#');return `<article class="card"><div class="card-media"><img src="${esc(image)}" alt="${esc(o.title||'عرض NIVORA')}" loading="lazy" decoding="async"></div><div class="card-body"><span class="tag">${esc(o.source||'عرض')}</span><h3>${esc(o.title||'عرض مميز')}</h3><p class="muted">${esc(o.description||'')}</p><div class="price">${o.price?money(Number(o.price)):''} ${o.oldPrice?`<span class="old">${money(Number(o.oldPrice))}</span>`:''}</div><div class="card-actions"><a class="btn-primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer nofollow">عرض المنتج</a></div></div></article>`}).join(''):`<div class="empty" style="grid-column:1/-1">لا توجد عروض منشورة حالياً.</div>`;
