  shell(`<section class="page container"><div class="page-title"><div class="eyebrow">SMART SOURCING</div><h1>استيراد منتج من رابط</h1><p class="muted">الصق رابط صفحة المنتج العامة من Amazon أو Noon أو Alibaba أو AliExpress. راجع البيانات قبل نشر المنتج.</p></div><div class="panel"><form id="import-form"><div class="form-row"><label>رابط المنتج</label><input class="field" id="import-url" type="url" required placeholder="https://..."></div><button class="btn-primary" id="import-btn">استيراد ومعاينة</button><div id="import-msg" class="message" style="margin-top:12px"></div></form></div><div id="import-preview" style="margin-top:18px"></div></section>`);
  $("#import-form").onsubmit=async e=>{e.preventDefault();const btn=$("#import-btn"),msg=$("#import-msg"),preview=$("#import-preview");btn.disabled=true;btn.textContent="جارٍ قراءة صفحة المنتج...";msg.className="message";try{
    const result=await window.NivoraAPI.request("/imports/product",{method:"POST",body:JSON.stringify({url:$("#import-url").value.trim()})});
    const p=result.product; const suggested=Math.max(0,Math.ceil(Number(p.price||0)*1.45));
    preview.innerHTML=`<div class="panel"><div class="section-head"><div><div class="eyebrow">PREVIEW</div><h2>${esc(p.title)}</h2><p class="muted">${esc(p.categoryName)} • المصدر: ${esc(p.source)}</p></div></div><div class="grid">${(p.images||[]).slice(0,6).map(x=>`<img src="${esc(x)}" alt="${esc(p.title)}" style="width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:10px;background:#111" loading="lazy">`).join("")}</div><div class="form-row" style="margin-top:18px"><label>سعر البيع بالجنيه المصري</label><input class="field" id="import-sale-price" type="number" min="0" step="0.01" value="${suggested}"></div><div class="form-row"><label>المخزون</label><input class="field" id="import-stock" type="number" min="0" step="1" value="0"></div><div class="form-row"><label>الوصف</label><textarea class="field" id="import-desc" rows="5">${esc(p.description||"")}</textarea></div><div class="toolbar"><button class="btn-primary" id="publish-import">حفظ المنتج في المتجر</button><button class="btn" id="discard-import" type="button">إلغاء</button></div></div>`;
    $("#publish-import").onclick=async()=>{const b=$("#publish-import");b.disabled=true;b.textContent="جارٍ الحفظ...";try{const id=await window.NivoraFirebase.saveProduct({id:p.externalProductId?`${p.source}-${String(p.externalProductId).replace(/[^A-Za-z0-9_-]/g,"-").slice(0,100)}`:undefined,name:p.title,title:p.title,desc:p.description||"",description:p.description||"",img:p.images?.[0]||"assets/logo/logo-transparent.webp",images:p.images||[],price:Number($("#import-sale-price").value||0),costPrice:Number(p.price||0),source:p.source,sourceUrl:p.sourceUrl,sku:p.sku||"",brand:p.brand||"",category:p.category,categoryName:p.categoryName,cat:p.category,catName:p.categoryName,stock:Number($("#import-stock").value||0),status:"active",currency:"EGP",importedAt:p.importedAt});preview.innerHTML=`<div class="message show">تم حفظ المنتج بنجاح برقم ${esc(id)} وأصبح متاحًا في الكتالوج.</div>`;await window.NivoraFirebase.trackEvent({type:"admin_product_import",productId:String(id),metadata:{source:p.source,category:p.category}})}catch(err){b.disabled=false;b.textContent="حفظ المنتج في المتجر";alert(err.message)}};
    $("#discard-import").onclick=()=>preview.innerHTML="";
  }catch(err){msg.textContent=err.message||"تعذر الاستيراد";msg.classList.add("show")}finally{btn.disabled=false;btn.textContent="استيراد ومعاينة"}};
